messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Low‑poly Humanoid Cycle</title>
  <style>
    body { margin: 0; overflow: hidden; background: #222; }
    #info {
      position: absolute; bottom: 20px; left: 20px;
      color: #ccc; font-family: monospace; font-size: 14px;
      background: rgba(0,0,0,0.6); padding: 6px 12px; border-radius: 6px;
      pointer-events: none;
    }
  </style>
</head>
<body>
  <div id="info">🚶‍♂️ Walk (3s) → 🏃 Run (3s) → 🧍 Stand (2s) → loop</div>
  <script type="importmap">
    {
      "imports": {
        "three": "./three.module.js"
      }
    }
  </script>
  <script type="module">
    import * as THREE from 'three';

    // --- setup scene ---
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x2a2a3a);

    // --- camera (side-on, slightly elevated) ---
    const camera = new THREE.PerspectiveCamera(40, window.innerWidth / window.innerHeight, 0.1, 100);
    camera.position.set(3.2, 2.0, 5.8);
    camera.lookAt(0, 1.0, 0);

    // --- renderer ---
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(window.devicePixelRatio);
    document.body.appendChild(renderer.domElement);

    // --- lights ---
    const ambient = new THREE.AmbientLight(0x404060);
    scene.add(ambient);
    const dirLight = new THREE.DirectionalLight(0xffeedd, 1.2);
    dirLight.position.set(3, 5, 4);
    scene.add(dirLight);
    const fillLight = new THREE.DirectionalLight(0x4466aa, 0.6);
    fillLight.position.set(-2, 1, 3);
    scene.add(fillLight);

    // --- ground (treadmill style) ---
    const groundMat = new THREE.MeshStandardMaterial({
      color: 0x3a4a5a,
      roughness: 0.8,
      metalness: 0.1,
    });
    const ground = new THREE.Mesh(new THREE.BoxGeometry(6, 0.15, 2.5), groundMat);
    ground.position.y = -0.075;
    scene.add(ground);

    // subtle grid lines
    const gridMat = new THREE.LineBasicMaterial({ color: 0x5a6a7a });
    const gridGeo = new THREE.GridHelper(6, 10, 0x6a7a8a, 0x4a5a6a);
    gridGeo.position.y = 0.01;
    scene.add(gridGeo);

    // --- build low-poly humanoid ---
    const group = new THREE.Group();
    group.position.set(0, 0, 0);

    const bodyMat = new THREE.MeshStandardMaterial({
      color: 0x8ab5d9,
      roughness: 0.6,
      flatShading: true,
    });
    const limbMat = new THREE.MeshStandardMaterial({
      color: 0x6a8aaf,
      roughness: 0.7,
      flatShading: true,
    });
    const shoeMat = new THREE.MeshStandardMaterial({
      color: 0x334455,
      roughness: 0.9,
    });
    const headMat = new THREE.MeshStandardMaterial({
      color: 0xbbd9ee,
      roughness: 0.5,
    });

    // --- torso ---
    const torso = new THREE.Mesh(new THREE.BoxGeometry(0.9, 1.2, 0.5), bodyMat);
    torso.position.y = 0.6;
    group.add(torso);

    // --- head ---
    const head = new THREE.Mesh(new THREE.BoxGeometry(0.7, 0.7, 0.6), headMat);
    head.position.y = 1.3;
    head.position.z = 0.05;
    group.add(head);

    // --- left arm (upper) ---
    const leftArm = new THREE.Mesh(new THREE.BoxGeometry(0.25, 0.9, 0.25), limbMat);
    leftArm.position.set(-0.6, 0.9, 0);
    group.add(leftArm);

    // --- right arm (upper) ---
    const rightArm = new THREE.Mesh(new THREE.BoxGeometry(0.25, 0.9, 0.25), limbMat);
    rightArm.position.set(0.6, 0.9, 0);
    group.add(rightArm);

    // --- left forearm ---
    const leftFore = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.8, 0.2), limbMat);
    leftFore.position.set(-0.6, 0.15, 0);
    group.add(leftFore);

    // --- right forearm ---
    const rightFore = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.8, 0.2), limbMat);
    rightFore.position.set(0.6, 0.15, 0);
    group.add(rightFore);

    // --- left thigh ---
    const leftThigh = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.9, 0.3), limbMat);
    leftThigh.position.set(-0.3, -0.45, 0);
    group.add(leftThigh);

    // --- right thigh ---
    const rightThigh = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.9, 0.3), limbMat);
    rightThigh.position.set(0.3, -0.45, 0);
    group.add(rightThigh);

    // --- left shin ---
    const leftShin = new THREE.Mesh(new THREE.BoxGeometry(0.25, 0.8, 0.25), limbMat);
    leftShin.position.set(-0.3, -1.1, 0);
    group.add(leftShin);

    // --- right shin ---
    const rightShin = new THREE.Mesh(new THREE.BoxGeometry(0.25, 0.8, 0.25), limbMat);
    rightShin.position.set(0.3, -1.1, 0);
    group.add(rightShin);

    // --- feet (shoes) ---
    const leftFoot = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.2, 0.45), shoeMat);
    leftFoot.position.set(-0.3, -1.5, 0.1);
    group.add(leftFoot);
    const rightFoot = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.2, 0.45), shoeMat);
    rightFoot.position.set(0.3, -1.5, 0.1);
    group.add(rightFoot);

    // --- store limbs for animation ---
    const limbs = {
      leftArm, rightArm, leftFore, rightFore,
      leftThigh, rightThigh, leftShin, rightShin,
      leftFoot, rightFoot,
      torso, head, // lean whole body
    };

    // initial offsets (relative to group pivot)
    // center pivot at hip height
    group.position.y = 1.5;
    scene.add(group);

    // --- animation control ---
    const clock = new THREE.Clock();
    let cycleTime = 0;
    const CYCLE_DURATION = 10; // 2 stand + 3 walk + 3 run + 2 stand

    // phase helpers
    function getPhase(t) {
      const cycle = t % CYCLE_DURATION;
      if (cycle < 2) return 'stand1';
      if (cycle < 5) return 'walk';
      if (cycle < 8) return 'run';
      return 'stand2';
    }

    function getLocalProgress(t, start, duration) {
      const cycle = t % CYCLE_DURATION;
      const local = cycle - start;
      return Math.min(Math.max(local / duration, 0), 1);
    }

    // --- animate limbs ---
    function animate(time) {
      const t = time / 1000; // seconds
      const cycle = t % CYCLE_DURATION;
      const phase = getPhase(t);

      // default stand pose (neutral)
      const standPose = () => {
        // arms
        limbs.leftArm.rotation.x = 0.1;
        limbs.leftArm.rotation.z = 0.05;
        limbs.rightArm.rotation.x = -0.1;
        limbs.rightArm.rotation.z = -0.05;
        limbs.leftFore.rotation.x = 0.15;
        limbs.rightFore.rotation.x = -0.15;
        // legs
        limbs.leftThigh.rotation.x = 0.05;
        limbs.rightThigh.rotation.x = -0.05;
        limbs.leftShin.rotation.x = 0.1;
        limbs.rightShin.rotation.x = -0.1;
        limbs.leftFoot.rotation.x = 0;
        limbs.rightFoot.rotation.x = 0;
        // torso lean
        limbs.torso.rotation.x = 0;
        limbs.torso.rotation.z = 0;
        limbs.head.rotation.x = 0.05;
      };

      // walking pose (cyclic)
      const walkCycle = (progress, speedFactor = 1, amplitude = 1) => {
        const swing = Math.sin(progress * 2 * Math.PI * 2) * 0.6 * amplitude;
        const swing2 = Math.sin(progress * 2 * Math.PI * 2 + 0.5) * 0.6 * amplitude;
        const elbowSwing = Math.sin(progress * 2 * Math.PI * 2 + 1.2) * 0.5 * amplitude;
        const kneeSwing = Math.sin(progress * 2 * Math.PI * 2 + 1.8) * 0.5 * amplitude;

        // arms (opposite to legs)
        limbs.leftArm.rotation.x = 0.3 + swing * 0.7;
        limbs.leftArm.rotation.z = 0.1 + swing * 0.2;
        limbs.rightArm.rotation.x = -0.3 - swing * 0.7;
        limbs.rightArm.rotation.z = -0.1 - swing * 0.2;

        limbs.leftFore.rotation.x = 0.5 + elbowSwing * 0.8;
        limbs.rightFore.rotation.x = -0.5 - elbowSwing * 0.8;

        // legs
        limbs.leftThigh.rotation.x = -0.2 - swing * 0.9;
        limbs.rightThigh.rotation.x = 0.2 + swing * 0.9;
        limbs.leftShin.rotation.x = 0.3 + kneeSwing * 0.9;
        limbs.rightShin.rotation.x = -0.3 - kneeSwing * 0.9;

        limbs.leftFoot.rotation.x = swing * 0.3;
        limbs.rightFoot.rotation.x = -swing * 0.3;

        // torso slight lean
        limbs.torso.rotation.x = 0.05 * amplitude;
        limbs.torso.rotation.z = swing * 0.05;
        limbs.head.rotation.x = 0.1 * amplitude;
      };

      // run cycle (faster, larger, forward lean)
      const runCycle = (progress) => {
        const amp = 1.7;
        const speed = 3.2;
        const swing = Math.sin(progress * 2 * Math.PI * speed) * 1.2 * amp;
        const swing2 = Math.sin(progress * 2 * Math.PI * speed + 0.7) * 1.2 * amp;
        const elbowSwing = Math.sin(progress * 2 * Math.PI * speed + 1.5) * 1.0 * amp;
        const kneeSwing = Math.sin(progress * 2 * Math.PI * speed + 2.0) * 1.0 * amp;

        // arms (bigger, more bent)
        limbs.leftArm.rotation.x = 0.8 + swing * 0.9;
        limbs.leftArm.rotation.z = 0.2 + swing * 0.3;
        limbs.rightArm.rotation.x = -0.8 - swing * 0.9;
        limbs.rightArm.rotation.z = -0.2 - swing * 0.3;

        limbs.leftFore.rotation.x = 1.2 + elbowSwing * 1.0;
        limbs.rightFore.rotation.x = -1.2 - elbowSwing * 1.0;

        // legs (higher knee, more thrust)
        limbs.leftThigh.rotation.x = -0.5 - swing * 1.3;
        limbs.rightThigh.rotation.x = 0.5 + swing * 1.3;
        limbs.leftShin.rotation.x = 0.8 + kneeSwing * 1.2;
        limbs.rightShin.rotation.x = -0.8 - kneeSwing * 1.2;

        limbs.leftFoot.rotation.x = swing * 0.5;
        limbs.rightFoot.rotation.x = -swing * 0.5;

        // forward lean
        limbs.torso.rotation.x = 0.25 * amp;
        limbs.torso.rotation.z = swing * 0.1;
        limbs.head.rotation.x = 0.2 * amp;
      };

      // --- blend between phases ---
      if (phase === 'stand1') {
        standPose();
      } else if (phase === 'walk') {
        const progress = (cycle - 2) / 3;
        walkCycle(progress, 1, 1);
      } else if (phase === 'run') {
        const progress = (cycle - 5) / 3;
        runCycle(progress);
      } else { // stand2
        standPose();
      }

      // small idle bob for standing (subtle)
      if (phase === 'stand1' || phase === 'stand2') {
        const bob = Math.sin(t * 1.5) * 0.015;
        group.position.y = 1.5 + bob;
        limbs.torso.rotation.x += Math.sin(t * 1.2) * 0.01;
      } else {
        // dynamic bounce for walk/run
        const bounce = phase === 'walk' 
          ? Math.sin((cycle - 2) * 2 * Math.PI * 2) * 0.03
          : Math.sin((cycle - 5) * 2 * Math.PI * 3.2) * 0.06;
        group.position.y = 1.5 + bounce;
      }

      // camera side-on, subtle orbit for interest
      const camAngle = 0.15 * Math.sin(t * 0.08);
      camera.position.x = 3.2 + 0.4 * Math.sin(camAngle);
      camera.position.z = 5.8 + 0.3 * Math.cos(camAngle);
      camera.lookAt(0, 1.0, 0);
    }

    // --- render loop ---
    function render() {
      const time = clock.getElapsedTime() * 1000;
      animate(time);
      renderer.render(scene, camera);
      requestAnimationFrame(render);
    }

    render();

    // --- resize ---
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });
  </script>
</body>
</html>
```
